<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Save User Input</title>
    <style>
        body {
            font-family: Arial, sans-serif;
            margin: 20px;
        }
        .form-container {
            max-width: 400px;
            margin: auto;
        }
        label {
            display: block;
            margin-bottom: 5px;
        }
        input[type="text"] {
            width: calc(100% - 22px);
            padding: 10px;
            margin-bottom: 15px;
            border: 1px solid #ccc;
            border-radius: 4px;
        }
        button {
            padding: 10px 20px;
            background-color: #007BFF;
            color: white;
            border: none;
            border-radius: 4px;
            cursor: pointer;
        }
        button:hover {
            background-color: #0056b3;
        }
    </style>
</head>
<body>

<div class="form-container">
    <h2>Enter Your Text</h2>
    <form id="saveForm">
        <label for="userInput">Text:</label>
        <input type="text" id="userInput" name="userInput" required>
        <button type="submit">Save</button>
    </form>
    <p id="message"></p>
</div>

<script>
    document.getElementById('saveForm').addEventListener('submit', function(event) {
        event.preventDefault(); // Prevent the form from submitting in the traditional way

        const userInput = document.getElementById('userInput').value;

        if (userInput.trim() === '') {
            document.getElementById('message').textContent = 'Please enter some text.';
            return;
        }

        localStorage.setItem('userInput', userInput); // Save the text to local storage
        document.getElementById('message').textContent = 'Text saved successfully!';
        document.getElementById('userInput').value = ''; // Clear the input field
